function isFormControl(el){return el.nodeType===1&&['INPUT','TEXTAREA','SELECT'].includes(el.tagName)}
function markTouched(event){const el=event.target;if(el&&el.setAttribute&&isFormControl(el))el.setAttribute('data-touched','1')}
function controlDirty(el){if(el===document.activeElement||el.getAttribute('data-touched')==='1')return true;return el.type==='file'&&!!(el.files&&el.files.length)}
